theorem Finset.prod_pos.{u_1, u_2} {ι : Type u_1} {R : Type u_2} [CommMonoidWithZero R] [PartialOrder R]
  [ZeroLEOneClass R] [PosMulStrictMono R] [Nontrivial R] {f : ι → R} {s : Finset ι}
  (h0 : ∀ i ∈ s, 0 < f i) : 0 < ∏ i ∈ s, f i

theorem Finset.prod_le_prod_of_subset_of_one_le.{u_1, u_2} {ι : Type u_1} {R : Type u_2}
  [CommMonoidWithZero R] [Preorder R] [ZeroLEOneClass R] [PosMulMono R] {f : ι → R} {s t : Finset ι}
  (h : s ⊆ t) (hf0 : ∀ i ∈ s, 0 ≤ f i) (hf : ∀ i ∈ t, i ∉ s → 1 ≤ f i) : ∏ i ∈ s, f i ≤ ∏ i ∈ t, f i

theorem Finset.le_prod_max_one.{u_1, u_4} {ι : Type u_1} {s : Finset ι} {M : Type u_4}
  [CommMonoidWithZero M] [LinearOrder M] [ZeroLEOneClass M] [PosMulMono M] {i : ι} (hi : i ∈ s)
  (f : ι → M) : f i ≤ ∏ i ∈ s, max (f i) 1

theorem Finset.prod_le_prod_of_subset_of_le_one.{u_1, u_2} {ι : Type u_1} {R : Type u_2}
  [CommMonoidWithZero R] [Preorder R] [ZeroLEOneClass R] [PosMulMono R] {f : ι → R} {s t : Finset ι}
  (h : s ⊆ t) (hf0 : ∀ i ∈ t, 0 ≤ f i) (hf : ∀ i ∈ t, i ∉ s → f i ≤ 1) : ∏ i ∈ t, f i ≤ ∏ i ∈ s, f i

theorem Multiset.prod_map_nonneg.{u_1, u_2} {R : Type u_1} [CommMonoidWithZero R] [PartialOrder R]
  [ZeroLEOneClass R] [PosMulMono R] {α : Type u_2} {s : Multiset α} {f : α → R}
  (h : ∀ a ∈ s, 0 ≤ f a) : 0 ≤ (Multiset.map f s).prod

theorem Multiset.one_le_prod_map.{u_1, u_2} {R : Type u_1} [CommMonoidWithZero R] [PartialOrder R]
  [ZeroLEOneClass R] [PosMulMono R] {α : Type u_2} {s : Multiset α} {f : α → R}
  (h : ∀ a ∈ s, 1 ≤ f a) : 1 ≤ (Multiset.map f s).prod

theorem AddLECancellable.mul_tsub.{u} {R : Type u} [NonUnitalNonAssocSemiring R] [PartialOrder R]
  [CanonicallyOrderedAdd R] [Sub R] [OrderedSub R] [Std.Total fun x1 x2 => x1 ≤ x2] {a b c : R}
  (h : AddLECancellable (a * c)) : a * (b - c) = a * b - a * c

