theorem Finset.sq_sum_div_le_sum_sq_div.{u_1, u_2} {ι : Type u_1} {R : Type u_2} [Semifield R]
  [LinearOrder R] [IsStrictOrderedRing R] [ExistsAddOfLE R] (s : Finset ι) (f : ι → R) {g : ι → R}
  (hg : ∀ i ∈ s, 0 < g i) : (∑ i ∈ s, f i) ^ 2 / ∑ i ∈ s, g i ≤ ∑ i ∈ s, f i ^ 2 / g i

theorem IsAbsoluteValue.map_prod.{u_1, u_2, u_3} {ι : Type u_1} {R : Type u_2} {S : Type u_3}
  [CommSemiring R] [Nontrivial R] [CommRing S] [LinearOrder S] [IsStrictOrderedRing S] (abv : R → S)
