theorem finprod_mem_mul_distrib.{u_1, u_5} {α : Type u_1} {M : Type u_5} [CommMonoid M] {f g : α → M}
  {s : Set α} (hs : s.Finite) :
  ∏ᶠ (i : α) (_ : i ∈ s), f i * g i = (∏ᶠ (i : α) (_ : i ∈ s), f i) * ∏ᶠ (i : α) (_ : i ∈ s), g i

theorem finsum_induction.{u_2, u_4} {M : Type u_2} {α : Sort u_4} [AddCommMonoid M] {f : α → M}
  (p : M → Prop) (hp₀ : p 0) (hp₁ : ∀ (x y : M), p x → p y → p (x + y)) (hp₂ : ∀ (i : α), p (f i)) :
