theorem finprod_mem_congr.{u_1, u_5} {α : Type u_1} {M : Type u_5} [CommMonoid M] {f g : α → M}
  {s t : Set α} (h₀ : s = t) (h₁ : ∀ x ∈ t, f x = g x) :
  ∏ᶠ (i : α) (_ : i ∈ s), f i = ∏ᶠ (i : α) (_ : i ∈ t), g i

theorem finsum_add_distrib.{u_1, u_5} {α : Type u_1} {M : Type u_5} [AddCommMonoid M] {f g : α → M}
  (hf : Function.HasFiniteSupport f) (hg : Function.HasFiniteSupport g) :
  ∑ᶠ (i : α), (f i + g i) = ∑ᶠ (i : α), f i + ∑ᶠ (i : α), g i

theorem MulEquivClass.map_finprod.{u_2, u_3, u_4, u_7} {M : Type u_2} {N : Type u_3} {α : Sort u_4}
  [CommMonoid M] [CommMonoid N] {F : Type u_7} [EquivLike F M N] [MulEquivClass F M N] (g : F)
