theorem finprod_mem_mul_diff'.{u_1, u_5} {α : Type u_1} {M : Type u_5} [CommMonoid M] {f : α → M}
  {s t : Set α} (hst : s ⊆ t) (ht : (t ∩ Function.mulSupport f).Finite) :
  (∏ᶠ (i : α) (_ : i ∈ s), f i) * ∏ᶠ (i : α) (_ : i ∈ t \ s), f i = ∏ᶠ (i : α) (_ : i ∈ t), f i

theorem finsum_sub_distrib.{u_1, u_4} {α : Type u_1} {G : Type u_4} [SubtractionCommMonoid G] {f g : α → G}
  (hf : Function.HasFiniteSupport f) (hg : Function.HasFiniteSupport g) :
  ∑ᶠ (i : α), (f i - g i) = ∑ᶠ (i : α), f i - ∑ᶠ (i : α), g i

theorem finsum_mem_neg_distrib.{u_1, u_4} {α : Type u_1} {G : Type u_4} {s : Set α}
  [SubtractionCommMonoid G] (f : α → G) (hs : s.Finite) :
  ∑ᶠ (x : α) (_ : x ∈ s), -f x = -∑ᶠ (x : α) (_ : x ∈ s), f x

theorem AddMonoidHom.map_finsum_mem.{u_1, u_5, u_6} {α : Type u_1} {M : Type u_5} {N : Type u_6}
  [AddCommMonoid M] [AddCommMonoid N] {s : Set α} (f : α → M) (g : M →+ N) (hs : s.Finite) :
  g (∑ᶠ (j : α) (_ : j ∈ s), f j) = ∑ᶠ (i : α) (_ : i ∈ s), g (f i)

theorem finsum_mem_add_distrib'.{u_1, u_5} {α : Type u_1} {M : Type u_5} [AddCommMonoid M] {f g : α → M}
  {s : Set α} (hf : (s ∩ Function.support f).Finite) (hg : (s ∩ Function.support g).Finite) :
  ∑ᶠ (i : α) (_ : i ∈ s), (f i + g i) = ∑ᶠ (i : α) (_ : i ∈ s), f i + ∑ᶠ (i : α) (_ : i ∈ s), g i

theorem finsum_mem_union.{u_1, u_5} {α : Type u_1} {M : Type u_5} [AddCommMonoid M] {f : α → M}
  {s t : Set α} (hst : Disjoint s t) (hs : s.Finite) (ht : t.Finite) :
  ∑ᶠ (i : α) (_ : i ∈ s ∪ t), f i = ∑ᶠ (i : α) (_ : i ∈ s), f i + ∑ᶠ (i : α) (_ : i ∈ t), f i

theorem finsum_mem_add_sdiff'.{u_1, u_5} {α : Type u_1} {M : Type u_5} [AddCommMonoid M] {f : α → M}
  {s t : Set α} (hst : s ⊆ t) (ht : (t ∩ Function.support f).Finite) :
  ∑ᶠ (i : α) (_ : i ∈ s), f i + ∑ᶠ (i : α) (_ : i ∈ t \ s), f i = ∑ᶠ (i : α) (_ : i ∈ t), f i

theorem MonoidHom.map_finprod_plift.{u_2, u_3, u_4} {M : Type u_2} {N : Type u_3} {α : Sort u_4}
  [CommMonoid M] [CommMonoid N] (f : M →* N) (g : α → M)
  (h : Function.HasFiniteMulSupport (g ∘ PLift.down)) : f (∏ᶠ (x : α), g x) = ∏ᶠ (x : α), f (g x)

theorem finsum_mem_finset_product.{u_1, u_2, u_5} {α : Type u_1} {β : Type u_2} {M : Type u_5}
  [AddCommMonoid M] (s : Finset (α × β)) (f : α × β → M) :
  ∑ᶠ (ab : α × β) (_ : ab ∈ s), f ab = ∑ᶠ (a : α) (b : β) (_ : (a, b) ∈ s), f (a, b)

theorem finprod_le_finprod'.{u_1, u_5} {α : Type u_1} {M : Type u_5} [CommMonoid M] {f g : α → M}
  [PartialOrder M] [MulLeftMono M] (hf : Function.HasFiniteMulSupport f)
  (hg : Function.HasFiniteMulSupport g) (h : f ≤ g) : ∏ᶠ (a : α), f a ≤ ∏ᶠ (a : α), g a

theorem finsum_eq_sum_plift_of_support_toFinset_subset.{u_2, u_4} {M : Type u_2} {α : Sort u_4}
  [AddCommMonoid M] {f : α → M} (hf : Function.HasFiniteSupport (f ∘ PLift.down))
  {s : Finset (PLift α)} (hs : Set.Finite.toFinset hf ⊆ s) : ∑ᶠ (i : α), f i = ∑ i ∈ s, f i.down

theorem mul_finsum_mem'.{u_1, u_7} {α : Type u_1} {R : Type u_7} [NonUnitalNonAssocSemiring R] {s : Set α}
  (f : α → R) (r : R) (hs : s.Finite) :
  r * ∑ᶠ (a : α) (_ : a ∈ s), f a = ∑ᶠ (a : α) (_ : a ∈ s), r * f a

