theorem AddMonoidHom.map_finsum_plift.{u_2, u_3, u_4} {M : Type u_2} {N : Type u_3} {α : Sort u_4}
  [AddCommMonoid M] [AddCommMonoid N] (f : M →+ N) (g : α → M)
  (h : Function.HasFiniteSupport (g ∘ PLift.down)) : f (∑ᶠ (x : α), g x) = ∑ᶠ (x : α), f (g x)

theorem finprod_dmem.{u_1, u_5} {α : Type u_1} {M : Type u_5} [CommMonoid M] {s : Set α}
  [DecidablePred fun x => x ∈ s] (f : (a : α) → a ∈ s → M) :
  ∏ᶠ (a : α) (h : a ∈ s), f a h = ∏ᶠ (a : α) (_ : a ∈ s), if h' : a ∈ s then f a h' else 1

theorem finprod_mem_induction.{u_1, u_5} {α : Type u_1} {M : Type u_5} [CommMonoid M] {f : α → M}
  {s : Set α} (p : M → Prop) (hp₀ : p 1) (hp₁ : ∀ (x y : M), p x → p y → p (x * y))
  (hp₂ : ∀ x ∈ s, p (f x)) : p (∏ᶠ (i : α) (_ : i ∈ s), f i)

theorem finprod_eq_prod_of_mulSupport_toFinset_subset.{u_1, u_5} {α : Type u_1} {M : Type u_5}
  [CommMonoid M] (f : α → M) (hf : Function.HasFiniteMulSupport f) {s : Finset α}
  (h : Set.Finite.toFinset hf ⊆ s) : ∏ᶠ (i : α), f i = ∏ i ∈ s, f i

theorem finsum_mem_sUnion.{u_1, u_5} {α : Type u_1} {M : Type u_5} [AddCommMonoid M] {f : α → M}
  {t : Set (Set α)} (h : t.PairwiseDisjoint id) (ht₀ : t.Finite) (ht₁ : ∀ x ∈ t, x.Finite) :
  ∑ᶠ (a : α) (_ : a ∈ ⋃₀ t), f a = ∑ᶠ (s : Set α) (_ : s ∈ t) (a : α) (_ : a ∈ s), f a

theorem finsum_apply.{u_6, u_7, u_8} {N : Type u_6} [AddCommMonoid N] {α : Type u_7} {ι : Type u_8}
  {f : ι → α → N} (hf : Function.HasFiniteSupport f) (a : α) :
