theorem Finset.support_of_fiberwise_sum_subset_image.{u_1, u_2, u_5} {α : Type u_1} {β : Type u_2}
  {M : Type u_5} [AddCommMonoid M] [DecidableEq β] (s : Finset α) (f : α → M) (g : α → β) :
