theorem AddEquivClass.map_finsum.{u_2, u_3, u_4, u_7} {M : Type u_2} {N : Type u_3} {α : Sort u_4}
  [AddCommMonoid M] [AddCommMonoid N] {F : Type u_7} [EquivLike F M N] [AddEquivClass F M N] (g : F)
