theorem finsum_mem_induction.{u_1, u_5} {α : Type u_1} {M : Type u_5} [AddCommMonoid M] {f : α → M}
  {s : Set α} (p : M → Prop) (hp₀ : p 0) (hp₁ : ∀ (x y : M), p x → p y → p (x + y))
  (hp₂ : ∀ x ∈ s, p (f x)) : p (∑ᶠ (i : α) (_ : i ∈ s), f i)

