  {s : Set α} (t : Set α) (h : s.Finite) :
  (∏ᶠ (i : α) (_ : i ∈ s ∩ t), f i) * ∏ᶠ (i : α) (_ : i ∈ s \ t), f i = ∏ᶠ (i : α) (_ : i ∈ s), f i

theorem finprod_mem_mul_distrib'.{u_1, u_5} {α : Type u_1} {M : Type u_5} [CommMonoid M] {f g : α → M}
  {s : Set α} (hf : (s ∩ Function.mulSupport f).Finite) (hg : (s ∩ Function.mulSupport g).Finite) :
  ∏ᶠ (i : α) (_ : i ∈ s), f i * g i = (∏ᶠ (i : α) (_ : i ∈ s), f i) * ∏ᶠ (i : α) (_ : i ∈ s), g i

