theorem finsum_mem_add_sdiff.{u_1, u_5} {α : Type u_1} {M : Type u_5} [AddCommMonoid M] {f : α → M}
  {s t : Set α} (hst : s ⊆ t) (ht : t.Finite) :
  ∑ᶠ (i : α) (_ : i ∈ s), f i + ∑ᶠ (i : α) (_ : i ∈ t \ s), f i = ∑ᶠ (i : α) (_ : i ∈ t), f i

theorem finprod_mul_distrib.{u_1, u_5} {α : Type u_1} {M : Type u_5} [CommMonoid M] {f g : α → M}
  (hf : Function.HasFiniteMulSupport f) (hg : Function.HasFiniteMulSupport g) :
  ∏ᶠ (i : α), f i * g i = (∏ᶠ (i : α), f i) * ∏ᶠ (i : α), g i

theorem finprod_mem_mul_sdiff'.{u_1, u_5} {α : Type u_1} {M : Type u_5} [CommMonoid M] {f : α → M}
  {s t : Set α} (hst : s ⊆ t) (ht : (t ∩ Function.mulSupport f).Finite) :
  (∏ᶠ (i : α) (_ : i ∈ s), f i) * ∏ᶠ (i : α) (_ : i ∈ t \ s), f i = ∏ᶠ (i : α) (_ : i ∈ t), f i

theorem finprod_apply_ne_zero.{u_7, u_8, u_9} {ι : Type u_7} {N₀ : Type u_8} {M₀ : Type u_9}
